"""Render the stickman film in sync with the dialogue generated by generate-audio.ts.

    python3 render.py                 # final: out/timeline.json + out/dialogue.wav -> out/ana-amzah-maak-faqat.mp4
    python3 render.py --preview       # silent layout preview with estimated timings (no API key needed)
    python3 render.py --stills 1,5,7  # PNG stills from the middle of the given lines
"""
import argparse
import json
import math
import os
import subprocess
import sys
from multiprocessing import Pool

import skia

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from rig import argb, PAPER, clamp  # noqa: E402
from shots import DIRECTION  # noqa: E402

OUT = os.path.join(HERE, 'out')
W, H, FPS = 1080, 1920, 30
TITLE = 'أنا أمزح معك فقط!'
FADES = {'shot_l15_home': 0.5, 'shot_l18_end': 0.8, 'shot_l11_g': 0.35, 'shot_l15_word': 0.3, 'shot_l1_gathering': 0.25}


# ------------------------------------------------------------------ audio helper
class Audio:
    def __init__(self, timeline):
        self.lines = timeline['lines']
        self.duration = timeline['duration']
        self._title = None

    def _line(self, spk, T, pad=0.0):
        for ln in self.lines:
            if ln['speaker'] == spk and ln['start'] - pad <= T < ln['end'] + pad:
                return ln
        return None

    def env(self, spk, T):
        ln = self._line(spk, T)
        if not ln:
            return 0.0
        i = (T - ln['start']) * FPS
        e = ln['env']
        a = e[min(len(e) - 1, int(i))]
        b = e[min(len(e) - 1, int(i) + 1)]
        v = a + (b - a) * (i - int(i))
        return clamp(v * 1.4)

    def speaking(self, spk, T):
        return self._line(spk, T, 0.15) is not None

    def smooth(self, spk, T):
        vals = [self.env(spk, T + k * 0.05) for k in range(-6, 7)]
        return sum(vals) / len(vals)

    def title(self, c, alpha, y):
        if alpha <= 0.01:
            return
        if self._title is None:
            self._title = make_title()
        img = self._title
        p = skia.Paint(AntiAlias=True)
        p.setAlphaf(alpha)
        c.drawImage(img, (W - img.width()) / 2, y, skia.SamplingOptions(skia.FilterMode.kLinear), p)


def make_title():
    from PIL import Image, ImageDraw, ImageFont
    font_path = os.path.join(HERE, 'assets', 'Lalezar-Regular.ttf')
    if not os.path.exists(font_path):
        font_path = '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
    font = ImageFont.truetype(font_path, 118)
    im = Image.new('RGBA', (980, 260), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rounded_rectangle((20, 30, 960, 230), 40, fill=(245, 239, 228, 235), outline=(28, 27, 26, 255), width=7)
    d.text((490, 128), TITLE, font=font, fill=(28, 27, 26, 255), anchor='mm', direction='rtl', language='ar')
    d.line((390, 205, 590, 205), fill=(217, 100, 74, 255), width=8)
    path = os.path.join(OUT, '_title.png')
    im.save(path)
    return skia.Image.open(path)


# ------------------------------------------------------------------ edit decision list
def build_edl(audio):
    lines = audio.lines
    starts = []
    for i, ln in enumerate(lines):
        if i == 0:
            starts.append(0.0)
        else:
            prev = lines[i - 1]
            starts.append((prev['end'] + ln['start']) / 2)
    edl = []
    for i, ln in enumerate(lines):
        a = starts[i]
        b = starts[i + 1] if i + 1 < len(lines) else audio.duration
        shots = DIRECTION.get(ln['index'], DIRECTION[1])
        tot = sum(w for w, _ in shots)
        t = a
        for w, fn in shots:
            d = (b - a) * w / tot
            edl.append((t, t + d, fn))
            t += d
    return edl


def find_shot(edl, T):
    for k, (a, b, fn) in enumerate(edl):
        if a <= T < b:
            return k
    return len(edl) - 1


def draw_frame(c, edl, audio, T, surfaces):
    k = find_shot(edl, T)
    a, b, fn = edl[k]
    t = T - a
    fade = FADES.get(fn.__name__, 0.0)
    if k > 0 and t < fade:
        pa, pb, pfn = edl[k - 1]
        sa, sb = surfaces
        ca = sa.getCanvas()
        ca.save()
        pfn(ca, T - pa, pb - pa, T, audio)
        ca.restore()
        cb = sb.getCanvas()
        cb.save()
        fn(cb, t, b - a, T, audio)
        cb.restore()
        c.drawImage(sa.makeImageSnapshot(), 0, 0)
        p = skia.Paint()
        p.setAlphaf(clamp(t / fade))
        c.drawImage(sb.makeImageSnapshot(), 0, 0, skia.SamplingOptions(), p)
    else:
        c.save()
        fn(c, t, b - a, T, audio)
        c.restore()


# ------------------------------------------------------------------ rendering
def render_chunk(args):
    timeline, f0, f1, path = args
    audio = Audio(timeline)
    edl = build_edl(audio)
    surf = skia.Surface(W, H)
    surfaces = (skia.Surface(W, H), skia.Surface(W, H))
    ff = subprocess.Popen(['ffmpeg', '-y', '-loglevel', 'error', '-f', 'rawvideo', '-pix_fmt', 'bgra',
                           '-s', f'{W}x{H}', '-r', str(FPS), '-i', '-', '-c:v', 'libx264', '-preset', 'medium',
                           '-crf', '19', '-pix_fmt', 'yuv420p', path], stdin=subprocess.PIPE)
    for f in range(f0, f1):
        T = f / FPS
        c = surf.getCanvas()
        c.clear(argb(PAPER))
        draw_frame(c, edl, audio, T, surfaces)
        ff.stdin.write(surf.toarray().tobytes())
    ff.stdin.close()
    ff.wait()
    return path


def preview_timeline():
    """estimated timings so the picture can be checked before the real audio exists"""
    sys.path.insert(0, HERE)
    import re
    src = open(os.path.join(HERE, '..', '..', 'src', 'components', 'DialogueStudio.tsx'), encoding='utf-8').read()
    script = re.search(r'USER_SAMPLE_SCRIPT = `(.*?)`;', src, re.S).group(1)
    turns = []
    for raw in script.split('\n'):
        r = raw.strip().strip('*')
        if not r:
            continue
        m = re.match(r'^(المرأة|الرجل|النهاية)\s*:\s*(.*)$', r)
        if m:
            turns.append([{'المرأة': 'woman', 'الرجل': 'man', 'النهاية': 'narrator'}[m.group(1)], m.group(2)])
        elif not turns:
            turns.append(['narrator', r])
        else:
            turns[-1][1] += ' ' + r
    lines, t = [], 0.0
    for i, (spk, text) in enumerate(turns):
        d = max(1.6, len(text) / 13.0)
        n = int(d * FPS)
        env = [clamp(0.55 + 0.45 * math.sin(k * 1.9) * math.sin(k * 0.37)) if (k // 9) % 5 else 0.05 for k in range(n)]
        lines.append(dict(index=i, speaker=spk, text=text, start=t, end=t + d, env=env))
        t += d + 0.4
    return dict(duration=t - 0.4, fps=FPS, lines=lines)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--preview', action='store_true')
    ap.add_argument('--stills', default='')
    ap.add_argument('--jobs', type=int, default=os.cpu_count() or 4)
    ap.add_argument('--start', type=float, default=0.0)
    ap.add_argument('--end', type=float, default=None)
    args = ap.parse_args()
    os.makedirs(OUT, exist_ok=True)

    if args.preview or args.stills:
        timeline = preview_timeline() if not os.path.exists(os.path.join(OUT, 'timeline.json')) or args.preview \
            else json.load(open(os.path.join(OUT, 'timeline.json')))
    else:
        tl_path = os.path.join(OUT, 'timeline.json')
        if not os.path.exists(tl_path):
            sys.exit('out/timeline.json not found - run generate-audio.ts first (or use --preview).')
        timeline = json.load(open(tl_path))

    audio = Audio(timeline)
    edl = build_edl(audio)
    print(f'duration {audio.duration:.2f}s, {len(audio.lines)} lines, {len(edl)} shots')

    if args.stills:
        surf = skia.Surface(W, H)
        surfaces = (skia.Surface(W, H), skia.Surface(W, H))
        for tok in args.stills.split(','):
            if ':' in tok:   # line:fraction
                li, fr = tok.split(':')
                ln = audio.lines[int(li)]
                T = ln['start'] + (ln['end'] - ln['start']) * float(fr)
            else:
                T = float(tok)
            c = surf.getCanvas()
            c.clear(argb(PAPER))
            draw_frame(c, edl, audio, T, surfaces)
            p = os.path.join(OUT, f'still_{tok.replace(":", "_")}.png')
            surf.makeImageSnapshot().save(p, skia.kPNG)
            print(p)
        return

    end = args.end if args.end is not None else audio.duration
    f_start, f_end = int(args.start * FPS), int(math.ceil(end * FPS))
    n = args.jobs
    step = math.ceil((f_end - f_start) / n)
    jobs = []
    for k in range(n):
        a, b = f_start + k * step, min(f_end, f_start + (k + 1) * step)
        if a < b:
            jobs.append((timeline, a, b, os.path.join(OUT, f'_chunk{k}.mp4')))
    with Pool(len(jobs)) as pool:
        parts = pool.map(render_chunk, jobs)
    lst = os.path.join(OUT, '_chunks.txt')
    with open(lst, 'w') as fh:
        fh.writelines(f"file '{p}'\n" for p in parts)

    name = 'preview-silent.mp4' if args.preview else 'ana-amzah-maak-faqat.mp4'
    final = os.path.join(OUT, name)
    cmd = ['ffmpeg', '-y', '-loglevel', 'error', '-f', 'concat', '-safe', '0', '-i', lst]
    if args.preview:
        cmd += ['-f', 'lavfi', '-t', f'{(f_end - f_start) / FPS:.3f}', '-i', 'anullsrc=r=48000:cl=stereo']
    else:
        cmd += ['-ss', f'{args.start:.3f}', '-t', f'{end - args.start:.3f}', '-i', os.path.join(OUT, 'dialogue.wav')]
    cmd += ['-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-ar', '48000', '-movflags', '+faststart', final]
    subprocess.run(cmd, check=True)
    for p in parts:
        os.remove(p)
    os.remove(lst)
    print(final)


if __name__ == '__main__':
    main()
